/**
 * @description 锚点导航
 * @param {boolean} needSafeDistance 是否需要预留出安全间距
 */
export function AnchorNavComponent(needSafeDistance = false) {
  $(() => {
    // 是否为Shopify2.0版本
    const isShopify2 = $('body').hasClass('theme-v2')
    const $anchorNavItem = $('.anchor-nav-box li')

    // 安全间距 -> 本身的高度
    const safeDistance = $('.anchor-nav-box').height()

    // 向左位移
    function scrollLeftFunc($currAnchorLi) {
      const lfPos = $currAnchorLi.data('lf-pos');
      const isFirst = $currAnchorLi.data('index') === 1;
      let scrollLfVal;
      if(isFirst){
        scrollLfVal = 0;
      } else {
        scrollLfVal = lfPos - 20
      }
      requestAnimationFrame(() => {
        $('.anchor-nav-component').stop().animate({
          scrollLeft: scrollLfVal
        }, 100, "linear");
      });
    }

    // 浏览器hash值锚点定位
    function hashAnchorFunc(currAnchorID) {
      if (currAnchorID) {
        const anchorIdTxt = currAnchorID.split('#')[1];
        const $currAnchorLi = $(`.anchor-nav-box li[data-anchor-id="${anchorIdTxt}"]`)
        if ($currAnchorLi.length === 0) {
          $(`.anchor-nav-box li:first-child`).trigger('click')
        } else {
          $currAnchorLi.trigger('click')
        }
      }
    }

    // 动态匹配当前Tab页签 并切换选中状态
    function currTab(windowScrollTop) {
      $('.common-title-component').each(function () {
        const $sectionAnchor = $(this).find('.anchor-id');
        if ($sectionAnchor.length != 0) {
          const anchorID = $sectionAnchor.attr('id');
          const sectionAnchorTop = $sectionAnchor.position().top
          const diffVal = windowScrollTop - sectionAnchorTop;
          if (diffVal > -60 && diffVal < 200) {
            const $currAnchorLi = $(`.anchor-nav-box li[data-anchor-id="${anchorID}"]`)
            $currAnchorLi.addClass('active').siblings().removeClass('active');
          }
        }
      })
    }

    // 页面滚动监听
    function pageScrollListener() {
      const $header = $('#shopify-section-header,#shopify-section-header-v2');
      const $siteHeader = $('.site-header') || $('jky-header') || $('header-v5');
      let headerH;
      $(window).scroll(() => {
        let currHeaderH;

        if (isShopify2) {
          const localeSwitcherH = $('#shopify-section-locale-switcher .locale-switcher').outerHeight() || 0;
          const announcementH = $('#shopify-section-header .announcement').outerHeight() || 0;
          const themeV2HeaderH = $('.theme-v2-header').outerHeight();
          currHeaderH = localeSwitcherH + announcementH + themeV2HeaderH;
        } else {
          currHeaderH = $siteHeader.outerHeight();
        }
        if (currHeaderH > 0) {
          headerH = currHeaderH;
        }

        const anchorNavTop = $('.anchor-nav-component').position().top
        const windowScrollTop = $(window).scrollTop();
        const diffVal = anchorNavTop - windowScrollTop;

        currTab(windowScrollTop);

        if (isShopify2) {
          if (diffVal <= headerH) {
            $('#shopify-section-locale-switcher').addClass('v2-ip-hide');
            $header.hide()
          } else {
            $('#shopify-section-locale-switcher').removeClass('v2-ip-hide')
            $header.show()
          }
        } else {
          if (diffVal <= headerH) {
            if (headerH + $siteHeader.position().top <= 0) {
              return;
            }
            $siteHeader.css("top", `${diffVal - headerH}px`)
          } else {
            $siteHeader.css("top", '0px')
          }
        }
      })
    }

    // 动态监听 锚点导航选中元素的变化
    function anchorNavActiveListener(){
      // 创建一个 MutationObserver 实例
      var observer = new MutationObserver(function(mutations) {
        mutations.forEach(function(mutation) {
          if (mutation.type === 'attributes' && mutation.attributeName === 'class') {
            // 当 class 属性变化时执行的操作
            if($(mutation.target).hasClass('active')){
              scrollLeftFunc($(mutation.target))
            }
          }
        });
      });

      // 配置观察选项
      var config = { attributes: true };

      // 针对每个目标元素开始观察
      $anchorNavItem.each(function() {
        observer.observe(this, config);
      });
    }

    // 2.0版本吸顶适配
    if (isShopify2) {
      $('html,body').addClass('overflow-unset');
    }


    // 移动端锚点导航监听
    if(window.innerWidth < 1024){
      $anchorNavItem.each(function (){
        const lfPos = $(this).position().left;
        $(this).attr('data-lf-pos',lfPos)
      })
      anchorNavActiveListener();
    }

    $anchorNavItem.on('click', function () {
      const anchorID = $(this).data('anchor-id');
      if (anchorID) {
        $('html, body').animate({
          scrollTop: $(`#${anchorID}`).offset().top - (needSafeDistance ? safeDistance : 0)
        },100, "linear");
        if (window.innerWidth < 1024) {
          scrollLeftFunc($(this))
        }
      }
    })

    const currAnchorID = window.location.hash;
    if (currAnchorID) {
      hashAnchorFunc(currAnchorID);
    } else {
      currTab($(window).scrollTop());
    }

    window.addEventListener('hashchange', () => {
      hashAnchorFunc(window.location.hash);
    })

    pageScrollListener();
  })
}
