import './index.less'
import { downloadFile } from '@utils/index.js'

export default class PhotovolaticManuals {
  constructor() {
    this.init()
  }
  init() {
    document.querySelectorAll('[data-download-manual]').forEach(item => {
      item.onclick = e => {
        e.preventDefault()

        const { link, sectionTitle, itemTitle, buttonText, } = e.target.dataset
        if (link) {
          e.target.classList.add('btn--loading')
          downloadFile(link)

          setTimeout(() => {
            e.target.classList.remove('btn--loading')
          }, 5000)
        }

        // 数据埋码
        this.GAEvent({
          module: sectionTitle,
          position: itemTitle,
          button_name: buttonText,
        })
      } 
    })
  }

  // 数据埋码
  GAEvent(params) {
    window.dataLayer.push({ "event_parameters": null });
    window.dataLayer.push({
        "event":"ga4Event",
        "event_name":"photovoltaics_user_clicks",
        "event_parameters":{
            "current_page": window.location.href, // current page url
            ...params
        }
    });
  }
}
