import './index.less'

import './sections/photovolatic-steps/index.less'

import PhotovolaticBanner from "../photovolatic-collection/sections/photovolatic-banner"
import { AnchorNavComponent } from "./sections/anchor-nav-component"
import PhotovolaticScenes from "../photovolatic-collection/sections/photovolatic-scenes"
import PhotovolaticSetup from "../photovolatic-collection/sections/photovolatic-setup"
import PhotovolaticManuals from "./sections/photovolatic-manuals"

import IndexSupport from '../photovolatic-collection/sections/index-support'



document.addEventListener('DOMContentLoaded', () => {
  // Banner
  new PhotovolaticBanner({ swiperContainer: ".swiper-balcony-banner", })

  AnchorNavComponent(true)

  // scenes
  document.querySelectorAll(".section-photovolatic-scenes").forEach((element) => {
    const id = element.getAttribute('id');
    new PhotovolaticScenes({
      pcEl: '#' + id + ' .swiper-balcony-tab-content-pc',
      mbEl: '#' + id + ' .swiper-balcony-tab-content-mb'
    })
  });

  // set-up
  new PhotovolaticSetup({ el: '.photovolatic-setup-wrap' })

  new PhotovolaticManuals()

  IndexSupport()
})
