import './index.less'
import { VideoPlayer, } from '@utils/index'

export default class PhotovolaticSetup {
  constructor({ el }) {
    this.DOM = document.querySelector(el)
    this.el = el

    if (this.DOM) {
      // 初始化视频播放器
      this.videoPlayer = new VideoPlayer({
        container: this.DOM,
        videoSelector: 'jky-video',
        onTrack: this.handleVideoTrack.bind(this)
      })
      
      // 初始化视频点击事件并观察视口
      this.videoPlayer.init().observe()
    }
  }

  // 处理视频跟踪事件
  handleVideoTrack(data, videoElement) {
    const { sectionTitle, videoUrl, poster, index, videoTitle } = data
    this.GAEvent({
      module: sectionTitle,
      position: videoTitle,
      button_name: Number(index) + 1,
      link: videoUrl || poster,
    })
  }

  // 数据埋码
  GAEvent(params) {
    window.dataLayer.push({ "event_parameters": null });
    window.dataLayer.push({
      "event":"ga4Event",
      "event_name":"photovoltaics_user_clicks",
      "event_parameters":{
        "current_page": window.location.href, // current page url
        ...params
      }
    });
  }
}
