import './index.less'

export default () => {
  if (window.innerWidth > 1024) {
      $(".index-support-item").mouseenter(function () {
        if ($(this).hasClass("active")) return
        $(this).parent().find(".index-support-item").removeClass("active")
        $(this).addClass("active")
      })
    } else {
      $(".index-support-item").click(function () {
        var $this = $(this),
          $next = $this.next();

        $next.slideToggle();
        $this.toggleClass('active');

         $(this).parent().find(".index-support-item_content_m").not($next).slideUp().prev().removeClass('active');
      })
    }

}
